func reconcileCuratedSecondTaskRevisions(ctx context.Context, tx pgx.Tx) error {
	for _, revision := range curatedSecondTaskRevisions {
		var previousID, currentID int64
		if err := tx.QueryRow(ctx, `
			select
				coalesce((select id from questions where source = 'curated' and text = $1), 0),
				coalesce((select id from questions where source = 'curated' and text = $2), 0)
		`, revision.previous, revision.current).Scan(&previousID, &currentID); err != nil {
			return fmt.Errorf("find revised curated task: %w", err)
		}
		if previousID == 0 {
			continue
		}
		if currentID != 0 && currentID != previousID {
			if _, err := tx.Exec(ctx, `
				update attempts set target_id = $1
				where target_type = 'question' and target_id = $2
			`, previousID, currentID); err != nil {
				return fmt.Errorf("preserve attempts for revised curated task: %w", err)
			}
			if _, err := tx.Exec(ctx, `
				update exam_runs set question_ids = array_replace(question_ids, $1, $2)
				where $1 = any(question_ids)
			`, currentID, previousID); err != nil {
				return fmt.Errorf("preserve exam runs for revised curated task: %w", err)
			}
			if _, err := tx.Exec(ctx, `delete from questions where id = $1 and source = 'curated'`, currentID); err != nil {
				return fmt.Errorf("remove superseded curated task: %w", err)
			}
		}
		if _, err := tx.Exec(ctx, `update questions set text = $1 where id = $2 and source = 'curated'`, revision.current, previousID); err != nil {
			return fmt.Errorf("revise curated task in place: %w", err)
		}
	}
	return nil
}

func seedCuratedSecondTasks(ctx context.Context, tx pgx.Tx) error {
	if err := validateCuratedSecondTaskCatalog(); err != nil {
		return err
	}
	if err := reconcileCuratedSecondTaskRevisions(ctx, tx); err != nil {
		return err
	}
	for _, task := range curatedSecondTasks() {
		var topicID int
		if err := tx.QueryRow(ctx, `select id from topics where title = $1`, task.topic).Scan(&topicID); err != nil {
			return fmt.Errorf("find topic for second curated task %q: %w", task.topic, err)
		}
		if _, err := tx.Exec(ctx, `
			insert into questions (topic_id, type, exam_kind, text, expected_answer, short_answer, difficulty, tags, source)
			values ($1, $8, $2, $3, $4, $5, $6, $7, 'curated')
			on conflict (text) do update set topic_id = excluded.topic_id, type = excluded.type,
				exam_kind = excluded.exam_kind, expected_answer = excluded.expected_answer,
				short_answer = excluded.short_answer, difficulty = excluded.difficulty,
				tags = excluded.tags, source = excluded.source
		`, topicID, task.kind, task.text, task.answer, task.short, task.difficulty, []string{task.kind, "variant", "curated-second"}, curatedQuestionType(task.kind)); err != nil {
			return fmt.Errorf("seed second curated task %q (%s): %w", task.topic, task.kind, err)
		}
	}
	return nil
}
